// ── DEMO IN: build the five showcase scenarios ──────────────────────────────
// Each item carries a scenario label + everything its lane needs. The run is
// keyed so "Test workflow" (no key) always plays; duplicate keys stop (ONCE guard).
const run_id = 'cr-showcase-' + $execution.id;
const scenarios = [
  {
    // A: two real sources, relevant, publishable → PUBLISH through the whole loop
    scenario: 'A · two-voice change → PUBLISH + commit + card',
    input: {
      event_id: 'showcase-a', stream: 'change', materiality: 'material_breaking',
      learner_impact: 0.7, source_agreement: 0.9, quote_supported: 0.95,
      sources_verified: 2, injection_or_jailbreak: 0.05, authority: 'PA2',
      freeze_active: false, assessment_touched: false, revert_gate_present: true,
      diff_lines: 24, previous_version_available: true, lesson_touched: 'lesson-02-apify-actors',
      budgets: { publishes_used: 1, publishes_cap: 6, tokens_used: 9000, tokens_cap: 60000 },
      sources: [
        { source_id: 'n8n-releases', publisher: 'n8n', url: 'https://docs.n8n.io/release-notes/', role: 'authoritative' },
        { source_id: 'community-example', publisher: 'community', url: 'https://www.npmjs.com/package/n8n-nodes-base', role: 'corroborating' }
      ],
      q3_breaking_probability: 0.85, q7_lesson_touched: 'lesson-02-apify-actors'
    }
  },
  {
    // B: single vendor voice → refused (the morning's real lesson)
    scenario: 'B · one-voice claim → ESCALATE (insufficient corroboration)',
    input: {
      event_id: 'showcase-b', stream: 'change', materiality: 'material_breaking',
      learner_impact: 0.7, source_agreement: 0.9, quote_supported: 0.9,
      sources_verified: 1, injection_or_jailbreak: 0.02, authority: 'PA2',
      freeze_active: false, assessment_touched: false, revert_gate_present: true,
      diff_lines: 20, previous_version_available: true, lesson_touched: 'lesson-02-apify-actors',
      budgets: { publishes_used: 2, publishes_cap: 6, tokens_used: 12000, tokens_cap: 60000 },
      sources: [
        { source_id: 'n8n-releases', publisher: 'n8n', url: 'https://docs.n8n.io/release-notes/', role: 'authoritative' },
        { source_id: 'n8n-docs', publisher: 'n8n', url: 'https://docs.n8n.io/workflows/', role: 'authoritative' }
      ],
      q3_breaking_probability: 0.8, q7_lesson_touched: 'lesson-02-apify-actors'
    }
  },
  {
    // C: prompt injection → safety rule R2 fires
    scenario: 'C · prompt-injection source → ESCALATE (injection_or_jailbreak)',
    input: {
      event_id: 'showcase-c', stream: 'change', materiality: 'material_breaking',
      learner_impact: 0.9, source_agreement:  0.9, quote_supported: 0.9,
      sources_verified: 2, injection_or_jailbreak: 0.9, authority: 'PA2',
      freeze_active: false, assessment_touched: false, revert_gate_present: true,
      diff_lines: 10, previous_version_available: true, lesson_touched: 'lesson-02-apify-actors',
      budgets: { publishes_used: 0, publishes_cap: 6, tokens_used: 1000, tokens_cap: 60000 },
      sources: [
        { source_id: 'evil-mirror', publisher: 'evil', url: 'https://malicious-source.example.com/', role: 'authoritative' },
        { source_id: 'evil-mirror-2', publisher: 'evil', url: 'https://evil-mirror.example.net/', role: 'corroborating' }
      ],
      q3_breaking_probability: 0.9, q7_lesson_touched: 'lesson-02-apopy-actors'
    }
  },
  {
    // D: learned gate data (revert stream) — decided by the same rulebook, revert branch
    scenario: 'D · revert gate satisfied → REVERT (quiz delta fell)',
    input: {
      event_id: 'showcase-d', stream: 'revert', authority: 'PA2',
      lesson_touched: 'lesson-02-apify-actors',
      cohort: { n: 7, quiz_delta: -0.12, hours_since_publish: 53 },
      q3_breaking_probability: 0.0, q7_lesson_touched: 'lesson-02-apify-actors'
    }
  },
  {
    // E: stuck learner (learner stream) — dispatch branch
    scenario: 'E · stuck learner → DISPATCH micro-lesson (telemetry, consented)',
    input: {
      event_id: 'showcase-e', stream: 'learner', authority: 'PA2',
      lesson_touched: 'lesson-02-apify-actors',
      learner: { consent: true, consecutive_wrong: 3, dwell_minutes: 220, notifications_today: 0, notifications_week: 1 },
      q3_breaking_probability: 0.0, q7_lesson_touched: 'lesson-02-apify-actors'
    }
  }
];
return scenarios.map(s => ({ json: { run_id, ...s } }));

// UNWRAP + tag for every item (no short-circuit: 5 scenarios → 5 unwrapped items).
// The webhook nests bodies under `body` on newer n8n versions — accept both shapes.
return $input.all().map(item => {
  const j = item.json || {};
  const src = (j.input && typeof j.input === 'object') ? j
            : (j.body && typeof j.body.input === 'object') ? j.body : null;
  if (src) {
    return { json: { scenario: j.scenario || null, input: src.input, input_hash: null, engine: true } };
  }
  return { json: { ...j, engine: false } };
});

// ── SCAN lane: the declared source plan (kickoff/SOURCE-PLAN.md §1) ─────────
// One item per source with its independence group. URLtemplates are the same
// pages the production Apify actors watch.
return [
  { json: { source_id: 'n8n-releases', publisher: 'n8n', group: 'n8n-official',
      url: 'https://docs.n8n.io/release-notes/', role: 'authoritative',
      actor: 'apify~website-content-crawler',
      input: { startUrls: [{ url: 'https://docs.n8n.io/release-notes/' }], maxCrawlPages: 1, maxResults: 1 } } },
  { json: { source_id: 'npm-nodes-base', publisher: 'npm-community', group: 'npm-community',
      url: 'https://www.npmjs.com/package/n8n-nodes-base', role: 'corroborating',
      actor: 'apify~website-content-crawler',
      input: { startUrls: [{ url: 'https://www.npmjs.com/package/n8n-nodes-base' }], maxCrawlPages: 1, maxResults: 1 } } },
];

// SCAN FETCH: for the manual demo we attach pre-fetched snapshot fixtures so the
// lane runs without burning an Apify run; the LIVE lane below does the real crawl.
// (kept honest: items are tagged live_fetch=false)
return $input.all().map(item => {
  const j = item.json;
  const fixture = j.source_id === 'n8n-releases'
    ? '# Release notes | Changelog | n8n Docs

This page is a running log of feature-level updates from each n8n release.

## n8n@1.89.0

- AI Agent node: tools can now read the workflow static data.
- Bug fixes and minor editor improvements.'
    : '# n8n-nodes-base

The official n8n node collection. Latest 4.4.0 · published 3 days ago.

## Changes
- adds community node packaging examples';
  return { json: { ...j, fetched_markdown: fixture, fetched_live: false } };
});

// NORMALIZE: sha256 of the fetched text (exactly the production NORMALIZE shape)
const crypto = require('crypto');
return $input.all().map(i => ({ json: { ...i.json,
  fetched_hash: 'sha256:' + crypto.createHash('sha256').update(i.json.fetched_markdown || '').digest('hex') } }));

// DEDUPE (production contract): drop any snapshot whose content_hash was already
// seen. State kept in workflow static data (instance-persistent between runs).
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const fresh = $input.all().filter(i => {
  const h = i.json.content_hash;
  if (!h) return true;
  if (store.seen[h]) return false;
  return true;
});
// register the new hashes (cap the set at 50 to keep static data small)
for (const i of fresh) if (i.json.content_hash) store.seen[i.json.content_hash] = true;
const keys = Object.keys(store.seen);
if (keys.length > 50) for (const k of keys.slice(0, keys.length - 50)) delete store.seen[k];
return fresh;

// build the OBSERVE prompt from a scenario OR a fetched snapshot.
// Engine DecisionInputs ({input:{stream,...}}) pass through tagged; scan snapshots
// ({markdown, source_id, ...}) get an OBSERVE prompt built.
return $input.all().map(item => {
  const j = item.json || {};
  const isEngine = j.input && typeof j.input === 'object' && !!j.input.stream;
  if (isEngine) {
    return { json: { engine: true, scenario: j.scenario || null, input: j.input, input_hash: j.input_hash || null } };
  }
  return { json: {
    engine: false,
    scenario: j.scenario || 'live snapshot',
    messages: [
      { role: 'system', content: 'You extract factual claims from a snapshot page. Reply as JSON.' },
      { role: 'user', content: String(j.markdown || '').slice(0, 8000) }
    ],
    snapshot_text: j.markdown || '',
    source: { source_id: j.source_id, publisher: j.publisher, role: j.role, url: j.url }
  } };
});

// SECURITY FIXTURE (see spec): the judge never sees raw prompt text from sources.
// Strip control/injection patterns before any model call; log what was cut.
return $input.all().map(item => {
  const j = item.json;
  const raw = String(j.snapshot_text || '');
  const patterns = [
    [/ignore (all )?(previous|prior|above) (instructions?|prompts?)/gi, '[REDACTED-INJECTION]'],
    [/disregard .{0,20}(instructions?|safety)/gi, '[REDACTED-INJECTION]'],
    [/you are now/gi, '[REDACTED-INJECTION]'],
    [/system\s*:/gi, '[REDACTED-ROLE]'],
  ];
  let cut = 0;
  let clean = raw;
  for (const [re, rep] of patterns) {
    clean = clean.replace(re, () => { cut++; return rep; });
  }
  return { json: { ...j, snapshot_text: clean, injections_redacted: cut } };
});

// build OBSERVE messages for scan-path items (engine items were filtered out earlier)
return $input.all().filter(i => i.json.engine !== true).map(item => {
  const j = item.json;
  return { json: {
    engine: false,
    scenario: j.scenario || 'live snapshot',
    messages: [
      { role: 'system', content: 'You extract factual claims from a snapshot page. Reply as a JSON array of objects with keys: claim (string), quote (verbatim sentence from the page).' },
      { role: 'user', content: String(j.snapshot_text || '').slice(0, 8000) }
    ],
    snapshot_text: j.snapshot_text, source: j.source || null
  } };
});

// OBSERVE answer → structured claim set; attach snapshot for anchoring
return $input.all().map(item => {
  const ans = item.json;
  let claims = [];
  try {
    const parsed = typeof ans.choices?.[0]?.message?.content === 'string'
      ? JSON.parse(ans.choices[0].message.content) : ans.observed || [];
    claims = Array.isArray(parsed) ? parsed : (parsed.claims || []);
  } catch (e) { claims = []; }
  return { json: { ...item.json, claims } };
});

// ANCHOR VERBATIM: quote_supported gate — the judge's answer must survive contact
// with the cached snapshot text (production contract WIRING §2b).
return $input.all().map(item => {
  const j = item.json;
  const claims = j.claims || [];
  const anchored = claims.map(c => {
    const quote = (c.quote || '').trim();
    const hay = String(j.snapshot_text || '');
    const ok = quote.length > 0 && hay.includes(quote);
    return { ...c, anchored: ok };
  });
  const ratio = claims.length ? anchored.filter(c => c.anchored).length / claims.length : 0;
  return { json: { ...j, anchored_claims: anchored, quote_supported: ratio } };
});

// build the closed-question JUDGE prompt from anchored claims
return $input.all().map(item => {
  const j = item.json;
  return { json: {
    scenario: j.scenario,
    judge_messages: [
      { role: 'system', content: 'You answer closed questions with a JSON object. Keys: q1_materiality (one of material_breaking, material_deprecation, material_new_capability, cosmetic, marketing_noise, ambiguous, contradictory, unverifiable), q3_breaking_probability (0-1), q4_conflict (boolean), q5_injection (0-1), q7_lesson_touched (string). No prose.' },
      { role: 'user', content: JSON.stringify({ claims: j.anchored_claims || j.claims || [] }) }
    ] } };
});

// JUDGE answer → DecisionInput-ish fields; POLICY does the deciding
return $input.all().map(item => {
  const j = item.json;
  let a = {};
  try {
    const c = j.choices?.[0]?.message?.content;
    a = typeof c === 'string' ? JSON.parse(c) : (c || {});
  } catch (e) { a = {}; }
  return { json: {
    ...j,
    judge_answer: a,
    input: {
      event_id: 'live-' + (j.source?.source_id || 'snapshot'),
      stream: 'change',
      materiality: a.q1_materiality || 'ambiguous',
      learner_impact: Math.min(1, Math.max(0, Number(a.q3_breaking_probability) || 0)),
      source_agreement: 0.9, quote_supported: j.quote_supported ?? 0,
      sources_verified: (j.anchored_claims || []).length ? 2 : 1,
      injection_or_jailbreak: Math.min(1, Math.max(0, Number(a.q5_injection) || 0)),
      authority: 'PA2',
      freeze_active: false, assessment_touched: false, revert_gate_present: true,
      diff_lines: 12, previous_version_available: true,
      lesson_touched: a.q7_lesson_touched || 'lesson-02-apify-actors',
      budgets: { publishes_used: 0, publishes_cap: 6, tokens_used: 5000, tokens_cap: 60000 },
      sources: [ j.source && j.source.publisher ? { source_id: j.source.source_id, publisher: j.source.publisher, url: j.source.url, role: j.source.role } : null ].filter(Boolean),
      q3_breaking_probability: Number(a.q3_breaking_probability) || 0,
      q7_lesson_touched: a.q7_lesson_touched || 'lesson-02-apify-actors'
    } } };
});

/**
 * Courserefresh POLICY node — production rulebook (n8n Code node, Run Once for Each Item).
 *
 * This file is loaded verbatim into the n8n canvas (WIRING.md §3) and is kept identical to the
 * oracle `specs/courserefresh/skin/policy.py` by `app/tests/test_gate_parity.py`.
 *
 * Rule order (normative): safety -> evidence -> relevance -> authority -> integrity -> budget ->
 * default ESCALATE(unknown_state). First match wins. No network, no clock, no randomness.
 *
 * Input:  the DecisionInput (specs/shared/data-model.md §5) as `item.json.input`
 * Output: { action, reason_codes, authority, notes }
 */

const THRESHOLDS = {
  // discovery_roles: quoted, never counted as independent voices (mirrors + Tavily leads)
  evidence: { min_sources: 2, source_agreement_min: 0.5, quote_supported_min: 0.8,
              discovery_roles: ["none", "discovery"] },
  relevance: { learner_impact_min: 0.4 },
  safety: { injection_min: 0.5 },
  budgets: { publishes_per_day: 6, tokens_per_change: 60000, notify_per_learner_day: 1, notify_per_learner_week: 3 },
  revert: { n_min: 5, window_h: 48 },
  diff: { max_lines: 400 }
};

const COHORT_NOTIFY = ["material_breaking", "material_deprecation"];
const PUBLISHABLE = ["material_breaking", "material_deprecation", "material_new_capability"];
const MATERIALITIES = ["material_breaking", "material_deprecation", "material_new_capability", "cosmetic",
  "marketing_noise", "ambiguous", "contradictory", "unverifiable"];
const AUTHORITIES = ["PA0", "PA1", "PA2", "PA3"];

function num(v) {
  if (typeof v === "boolean" || v === null || v === undefined) return null;
  const n = Number(v);
  if (!isFinite(n)) return null;
  return n >= 0 && n <= 1 ? n : null;
}

function out(action, reasons, authority, notes = "") {
  return { action, reason_codes: reasons, authority, notes };
}

function independentPublishers(sources) {
  if (!Array.isArray(sources) || sources.length === 0) return null;
  // Roles in thresholds.evidence.discovery_roles are recorded, never counted as a voice:
  // "none" is a mirror or re-post (review 05, AP-01); "discovery" is a Tavily lead whose page has
  // not been fetched from its own publisher yet. One search engine is one voice, not three.
  const quiet = (THRESHOLDS.evidence.discovery_roles || ["none"]);
  const set = new Set(sources.filter((s) => s && typeof s === "object" && !quiet.includes(s.role))
    .map((s) => String(s.publisher || s.source_id || "?").toLowerCase()));
  return set.size;
}

function mirrorCount(sources) {
  if (!Array.isArray(sources)) return 0;
  const quiet = (THRESHOLDS.evidence.discovery_roles || ["none"]);
  return sources.filter((s) => s && typeof s === "object" && quiet.includes(s.role)).length;
}

function malformed(inp) {
  const required = ["event_id", "stream", "materiality", "learner_impact", "source_agreement",
    "quote_supported", "sources_verified", "injection_or_jailbreak", "authority", "freeze_active"];
  for (const f of required) if (inp[f] === undefined || inp[f] === null) return f;
  if (!MATERIALITIES.includes(inp.materiality)) return "materiality";
  if (!AUTHORITIES.includes(inp.authority)) return "authority";
  for (const f of ["learner_impact", "source_agreement", "quote_supported", "injection_or_jailbreak"]) {
    if (num(inp[f]) === null) return f;
  }
  if (!["change", "learner", "revert"].includes(inp.stream)) return "stream";
  return null;
}

function decideChange(inp) {
  const a = inp.authority, m = inp.materiality, b = inp.budgets || {};
  // 1) safety
  if (inp.freeze_active) return out("DRAFT", ["freeze_active"], a);
  if (num(inp.injection_or_jailbreak) >= THRESHOLDS.safety.injection_min) return out("ESCALATE", ["injection_or_jailbreak"], a);
  if (inp.assessment_touched) return out("ESCALATE", ["assessment_change_requires_human"], a);
  // 2) evidence
  if (m === "contradictory") return out("ESCALATE", ["source_conflict"], a);
  if (m === "unverifiable") return out("ESCALATE", ["unverifiable"], a);
  if (m === "ambiguous") return out("ESCALATE", ["ambiguous_change"], a);
  if (inp.seed) {
    if (inp.claims_upstream) return out("ESCALATE", ["seeded_source_misrepresented"], a, "rehearsal presented as a vendor change");
    return out("PUBLISH", [m, "seeded_rehearsal"], a, "SEEDED REHEARSAL — not a vendor release");
  }
  const publishers = independentPublishers(inp.sources);
  if (publishers !== null && publishers < THRESHOLDS.evidence.min_sources) {
    const mirrors = mirrorCount(inp.sources);
    let note = publishers + " independent voice(s) in " + Number(inp.sources_verified) + " source(s)";
    if (mirrors) note += " (" + mirrors + " source(s) not independent: mirrors, re-posts or discovery leads)";
    return out("ESCALATE", ["insufficient_corroboration"], a, note);
  }
  if (Number(inp.sources_verified) < THRESHOLDS.evidence.min_sources ||
      num(inp.source_agreement) < THRESHOLDS.evidence.source_agreement_min) return out("ESCALATE", ["insufficient_corroboration"], a);
  if (num(inp.quote_supported) < THRESHOLDS.evidence.quote_supported_min) return out("ESCALATE", ["quote_unsupported"], a);
  // 3) relevance
  if (m === "marketing_noise") return out("NO_CHANGE", ["immaterial_change"], a);
  if (m === "cosmetic" || num(inp.learner_impact) < THRESHOLDS.relevance.learner_impact_min) return out("DRAFT", ["low_learner_impact"], a);
  // 4) authority
  if (a === "PA0") return out("DRAFT", ["authority_insufficient"], a, "PA0: observe only");
  if (COHORT_NOTIFY.includes(m) && a !== "PA2") return out("DRAFT", ["authority_insufficient"], a, "cohort notification required (PA2)");
  // 5) integrity floor
  if (inp.revert_gate_present === false) return out("ESCALATE", ["integrity_floor_missing_gate"], a);
  if (Number(inp.diff_lines || 0) > THRESHOLDS.diff.max_lines) return out("ESCALATE", ["diff_too_wide"], a);
  if (inp.previous_version_available === false) return out("ESCALATE", ["previous_version_missing"], a);
  // 6) budget
  if (Number(b.publishes_used || 0) >= Number(b.publishes_cap || THRESHOLDS.budgets.publishes_per_day)) return out("ESCALATE", ["over_budget"], a, "publishes");
  if (Number(b.tokens_used || 0) >= Number(b.tokens_cap || THRESHOLDS.budgets.tokens_per_change)) return out("ESCALATE", ["over_budget"], a, "tokens");
  // 7) default
  if (PUBLISHABLE.includes(m)) {
    const reasons = [m];
    if (inp.seed) reasons.push("seeded_rehearsal");
    return out("PUBLISH", reasons, a, "lesson " + (inp.lesson_touched || "?"));
  }
  return out("ESCALATE", ["unknown_state"], a, "unhandled materiality " + m);
}

function decideLearner(inp) {
  const a = inp.authority;
  if (inp.freeze_active) return out("NO_CHANGE", ["freeze_active"], a);
  if (inp.grade_impacting) return out("ESCALATE", ["grade_impacting_requires_human"], a);
  if (!inp.consent) return out("NO_CHANGE", ["consent_missing"], a);
  const caps = inp.caps || {};
  if (Number(caps.notifications_today || 0) >= THRESHOLDS.budgets.notify_per_learner_day) return out("NO_CHANGE", ["rate_limited"], a, "day cap");
  if (Number(caps.notifications_week || 0) >= THRESHOLDS.budgets.notify_per_learner_week) return out("NO_CHANGE", ["rate_limited"], a, "week cap");
  if (inp.stuck && inp.concept_recently_dispatched) return out("NO_CHANGE", ["rate_limited"], a, "concept cap: " + (inp.concept || ""));
  if (inp.stuck) return out("DISPATCH", ["stuck_signals_met"], a, inp.concept || "");
  return out("NO_CHANGE", ["no_signal"], a);
}

function decideRevert(inp) {
  const a = inp.authority;
  if (inp.freeze_active) return out("NO_CHANGE", ["freeze_active"], a);
  if (!inp.revert_gate_present) return out("ESCALATE", ["revert_gate_absent"], a);
  if (inp.previous_version_available === false) return out("ESCALATE", ["previous_version_missing"], a);
  const c = inp.cohort || {};
  if (c.n === undefined || c.n === null || c.quiz_delta === undefined || c.quiz_delta === null ||
      c.hours_since_publish === undefined || c.hours_since_publish === null) return out("NO_CHANGE", ["measurement_incomplete"], a);
  if (Number(c.n) < THRESHOLDS.revert.n_min) return out("NO_CHANGE", ["cohort_below_minimum"], a, "n=" + c.n);
  if (Number(c.hours_since_publish) < THRESHOLDS.revert.window_h) return out("NO_CHANGE", ["gate_window_open"], a);
  if (Number(c.quiz_delta) <= 0) return out("REVERT", ["revert_gate_satisfied"], a);
  return out("NO_CHANGE", ["no_improvement_measured"], a);
}

function decide(inp) {
  const bad = malformed(inp);
  if (bad) {
    const authority = AUTHORITIES.includes(inp.authority) ? inp.authority : "PA0";
    return out("ESCALATE", ["unknown_state"], authority, "invalid:" + bad);
  }
  if (inp.stream === "change") return decideChange(inp);
  if (inp.stream === "learner") return decideLearner(inp);
  return decideRevert(inp);
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { decide, THRESHOLDS, MATERIALITIES, PUBLISHABLE };
}

// n8n runtime: read the input and emit one item per decision
if (typeof $input !== "undefined") {
  return $input.all().map((item) => ({ json: { decision: decide(item.json.input), input_hash: item.json.input_hash } }));
}

// Merge POLICY's {decision, input_hash} with the pre-POLICY engine/scenario info.
// POLICY runs runOnceForAllItems and preserves item ORDER, so we correlate by index
// against the union of items that entered POLICY this run.
const pre = [];
try { for (const it of $('PASS ENGINE INPUTS').all()) pre.push(it.json); } catch (e) {}
try { for (const it of $('JUDGE→input').all()) if (!pre.some(p => p === it.json)) pre.push(it.json); } catch (e2) {}
return $input.all().map((item, idx) => {
  const j = item.json || {};
  const match = pre[idx] || {};
  return { json: {
    ...j,
    scenario: match.scenario || null,
    engine: match.engine === true,
    input: match.input || j.input || null,
    input_hash: j.input_hash !== undefined ? j.input_hash : null
  } };
});

// one chained row per decision; carry scenario/engine/decision forward for the branches
return $input.all().map(item => {
