// ({markdown, source_id, ...}) get an OBSERVE prompt built.
return $input.all().map(item => {
  const j = item.json || {};
  const isEngine = j.input && typeof j.input === 'object' && !!j.input.stream;
  if (isEngine) {
    return { json: { engine: true, scenario: j.scenario || null, input: j.input, input_hash: j.input_hash || null } };
  }
  return { json: {
    engine: false,
    scenario: j.scenario || 'live snapshot',
    messages: [
      { role: 'system', content: 'You extract factual claims from a snapshot page. Reply as JSON.' },
      { role: 'user', content: String(j.markdown || '').slice(0, 8000) }
    ],
    snapshot_text: j.markdown || '',
    source: { source_id: j.source_id, publisher: j.publisher, role: j.role, url: j.url }
  } };
});

// SECURITY FIXTURE (see spec): the judge never sees raw prompt text from sources.
// Strip control/injection patterns before any model call; log what was cut.
return $input.all().map(item => {
  const j = item.json;
  const raw = String(j.snapshot_text || '');
  const patterns = [
    [/ignore (all )?(previous|prior|above) (instructions?|prompts?)/gi, '[REDACTED-INJECTION]'],
    [/disregard .{0,20}(instructions?|safety)/gi, '[REDACTED-INJECTION]'],
    [/you are now/gi, '[REDACTED-INJECTION]'],
    [/system\s*:/gi, '[REDACTED-ROLE]'],
  ];
  let cut = 0;
  let clean = raw;
  for (const [re, rep] of patterns) {
    clean = clean.replace(re, () => { cut++; return rep; });
  }
  return { json: { ...j, snapshot_text: clean, injections_redacted: cut } };
});

// build OBSERVE messages for scan-path items (engine items were filtered out earlier)
return $input.all().filter(i => i.json.engine !== true).map(item => {
  const j = item.json;
  return { json: {
    engine: false,
    scenario: j.scenario || 'live snapshot',
    messages: [
      { role: 'system', content: 'You extract factual claims from a snapshot page. Reply as a JSON array of objects with keys: claim (string), quote (verbatim sentence from the page).' },
      { role: 'user', content: String(j.snapshot_text || '').slice(0, 8000) }
    ],
    snapshot_text: j.snapshot_text, source: j.source || null
  } };
});

// OBSERVE answer → structured claim set; attach snapshot for anchoring
return $input.all().map(item => {
  const ans = item.json;
  let claims = [];
  try {
    const parsed = typeof ans.choices?.[0]?.message?.content === 'string'
      ? JSON.parse(ans.choices[0].message.content) : ans.observed || [];
    claims = Array.isArray(parsed) ? parsed : (parsed.claims || []);
  } catch (e) { claims = []; }
  return { json: { ...item.json, claims } };
});

// ANCHOR VERBATIM: quote_supported gate — the judge's answer must survive contact
// with the cached snapshot text (production contract WIRING §2b).
return $input.all().map(item => {
  const j = item.json;
  const claims = j.claims || [];
  const anchored = claims.map(c => {
    const quote = (c.quote || '').trim();
    const hay = String(j.snapshot_text || '');
    const ok = quote.length > 0 && hay.includes(quote);
    return { ...c, anchored: ok };
  });
  const ratio = claims.length ? anchored.filter(c => c.anchored).length / claims.length : 0;
  return { json: { ...j, anchored_claims: anchored, quote_supported: ratio } };
});

// build the closed-question JUDGE prompt from anchored claims
return $input.all().map(item => {
  const j = item.json;
  return { json: {
    scenario: j.scenario,
    judge_messages: [
      { role: 'system', content: 'You answer closed questions with a JSON object. Keys: q1_materiality (one of material_breaking, material_deprecation, material_new_capability, cosmetic, marketing_noise, ambiguous, contradictory, unverifiable), q3_breaking_probability (0-1), q4_conflict (boolean), q5_injection (0-1), q7_lesson_touched (string). No prose.' },
      { role: 'user', content: JSON.stringify({ claims: j.anchored_claims || j.claims || [] }) }
    ] } };
});

// JUDGE answer → DecisionInput-ish fields; POLICY does the deciding
return $input.all().map(item => {
  const j = item.json;
  let a = {};
  try {
    const c = j.choices?.[0]?.message?.content;
    a = typeof c === 'string' ? JSON.parse(c) : (c || {});
  } catch (e) { a = {}; }
  return { json: {
    ...j,
    judge_answer: a,
    input: {
      event_id: 'live-' + (j.source?.source_id || 'snapshot'),
      stream: 'change',
      materiality: a.q1_materiality || 'ambiguous',
      learner_impact: Math.min(1, Math.max(0, Number(a.q3_breaking_probability) || 0)),
      source_agreement: 0.9, quote_supported: j.quote_supported ?? 0,
      sources_verified: (j.anchored_claims || []).length ? 2 : 1,
      injection_or_jailbreak: Math.min(1, Math.max(0, Number(a.q5_injection) || 0)),
      authority: 'PA2',
      freeze_active: false, assessment_touched: false, revert_gate_present: true,
      diff_lines: 12, previous_version_available: true,
      lesson_touched: a.q7_lesson_touched || 'lesson-02-apify-actors',
      budgets: { publishes_used: 0, publishes_cap: 6, tokens_used: 5000, tokens_cap: 60000 },
      sources: [ j.source && j.source.publisher ? { source_id: j.source.source_id, publisher: j.source.publisher, url: j.source.url, role: j.source.role } : null ].filter(Boolean),
      q3_breaking_probability: Number(a.q3_breaking_probability) || 0,
      q7_lesson_touched: a.q7_lesson_touched || 'lesson-02-apify-actors'
    } } };
});

/**
 * Courserefresh POLICY node — production rulebook (n8n Code node, Run Once for Each Item).
 *
 * This file is loaded verbatim into the n8n canvas (WIRING.md §3) and is kept identical to the
 * oracle `specs/courserefresh/skin/policy.py` by `app/tests/test_gate_parity.py`.
 *
 * Rule order (normative): safety -> evidence -> relevance -> authority -> integrity -> budget ->
 * default ESCALATE(unknown_state). First match wins. No network, no clock, no randomness.
 *
 * Input:  the DecisionInput (specs/shared/data-model.md §5) as `item.json.input`
 * Output: { action, reason_codes, authority, notes }
 */

const THRESHOLDS = {
  // discovery_roles: quoted, never counted as independent voices (mirrors + Tavily leads)
  evidence: { min_sources: 2, source_agreement_min: 0.5, quote_supported_min: 0.8,
              discovery_roles: ["none", "discovery"] },
  relevance: { learner_impact_min: 0.4 },
  safety: { injection_min: 0.5 },
  budgets: { publishes_per_day: 6, tokens_per_change: 60000, notify_per_learner_day: 1, notify_per_learner_week: 3 },
  revert: { n_min: 5, window_h: 48 },
  diff: { max_lines: 400 }
};

const COHORT_NOTIFY = ["material_breaking", "material_deprecation"];
const PUBLISHABLE = ["material_breaking", "material_deprecation", "material_new_capability"];
const MATERIALITIES = ["material_breaking", "material_deprecation", "material_new_capability", "cosmetic",
  "marketing_noise", "ambiguous", "contradictory", "unverifiable"];
const AUTHORITIES = ["PA0", "PA1", "PA2", "PA3"];

function num(v) {
  if (typeof v === "boolean" || v === null || v === undefined) return null;
  const n = Number(v);
  if (!isFinite(n)) return null;
  return n >= 0 && n <= 1 ? n : null;
}

function out(action, reasons, authority, notes = "") {
  return { action, reason_codes: reasons, authority, notes };
}

function independentPublishers(sources) {
  if (!Array.isArray(sources) || sources.length === 0) return null;
  // Roles in thresholds.evidence.discovery_roles are recorded, never counted as a voice:
  // "none" is a mirror or re-post (review 05, AP-01); "discovery" is a Tavily lead whose page has
  // not been fetched from its own publisher yet. One search engine is one voice, not three.
  const quiet = (THRESHOLDS.evidence.discovery_roles || ["none"]);
  const set = new Set(sources.filter((s) => s && typeof s === "object" && !quiet.includes(s.role))
    .map((s) => String(s.publisher || s.source_id || "?").toLowerCase()));
  return set.size;
}

function mirrorCount(sources) {
  if (!Array.isArray(sources)) return 0;
  const quiet = (THRESHOLDS.evidence.discovery_roles || ["none"]);
  return sources.filter((s) => s && typeof s === "object" && quiet.includes(s.role)).length;
}

function malformed(inp) {
  const required = ["event_id", "stream", "materiality", "learner_impact", "source_agreement",
    "quote_supported", "sources_verified", "injection_or_jailbreak", "authority", "freeze_active"];
  for (const f of required) if (inp[f] === undefined || inp[f] === null) return f;
  if (!MATERIALITIES.includes(inp.materiality)) return "materiality";
  if (!AUTHORITIES.includes(inp.authority)) return "authority";
  for (const f of ["learner_impact", "source_agreement", "quote_supported", "injection_or_jailbreak"]) {
    if (num(inp[f]) === null) return f;
  }
  if (!["change", "learner", "revert"].includes(inp.stream)) return "stream";
  return null;
}

function decideChange(inp) {
  const a = inp.authority, m = inp.materiality, b = inp.budgets || {};
  // 1) safety
  if (inp.freeze_active) return out("DRAFT", ["freeze_active"], a);
  if (num(inp.injection_or_jailbreak) >= THRESHOLDS.safety.injection_min) return out("ESCALATE", ["injection_or_jailbreak"], a);
  if (inp.assessment_touched) return out("ESCALATE", ["assessment_change_requires_human"], a);
  // 2) evidence
  if (m === "contradictory") return out("ESCALATE", ["source_conflict"], a);
  if (m === "unverifiable") return out("ESCALATE", ["unverifiable"], a);
  if (m === "ambiguous") return out("ESCALATE", ["ambiguous_change"], a);
  if (inp.seed) {
    if (inp.claims_upstream) return out("ESCALATE", ["seeded_source_misrepresented"], a, "rehearsal presented as a vendor change");
    return out("PUBLISH", [m, "seeded_rehearsal"], a, "SEEDED REHEARSAL — not a vendor release");
  }
  const publishers = independentPublishers(inp.sources);
  if (publishers !== null && publishers < THRESHOLDS.evidence.min_sources) {
    const mirrors = mirrorCount(inp.sources);
    let note = publishers + " independent voice(s) in " + Number(inp.sources_verified) + " source(s)";
    if (mirrors) note += " (" + mirrors + " source(s) not independent: mirrors, re-posts or discovery leads)";
    return out("ESCALATE", ["insufficient_corroboration"], a, note);
  }
  if (Number(inp.sources_verified) < THRESHOLDS.evidence.min_sources ||
      num(inp.source_agreement) < THRESHOLDS.evidence.source_agreement_min) return out("ESCALATE", ["insufficient_corroboration"], a);
  if (num(inp.quote_supported) < THRESHOLDS.evidence.quote_supported_min) return out("ESCALATE", ["quote_unsupported"], a);
  // 3) relevance
  if (m === "marketing_noise") return out("NO_CHANGE", ["immaterial_change"], a);
  if (m === "cosmetic" || num(inp.learner_impact) < THRESHOLDS.relevance.learner_impact_min) return out("DRAFT", ["low_learner_impact"], a);
  // 4) authority
  if (a === "PA0") return out("DRAFT", ["authority_insufficient"], a, "PA0: observe only");
  if (COHORT_NOTIFY.includes(m) && a !== "PA2") return out("DRAFT", ["authority_insufficient"], a, "cohort notification required (PA2)");
  // 5) integrity floor
  if (inp.revert_gate_present === false) return out("ESCALATE", ["integrity_floor_missing_gate"], a);
  if (Number(inp.diff_lines || 0) > THRESHOLDS.diff.max_lines) return out("ESCALATE", ["diff_too_wide"], a);
  if (inp.previous_version_available === false) return out("ESCALATE", ["previous_version_missing"], a);
  // 6) budget
  if (Number(b.publishes_used || 0) >= Number(b.publishes_cap || THRESHOLDS.budgets.publishes_per_day)) return out("ESCALATE", ["over_budget"], a, "publishes");
  if (Number(b.tokens_used || 0) >= Number(b.tokens_cap || THRESHOLDS.budgets.tokens_per_change)) return out("ESCALATE", ["over_budget"], a, "tokens");
  // 7) default
  if (PUBLISHABLE.includes(m)) {
    const reasons = [m];
    if (inp.seed) reasons.push("seeded_rehearsal");
    return out("PUBLISH", reasons, a, "lesson " + (inp.lesson_touched || "?"));
  }
  return out("ESCALATE", ["unknown_state"], a, "unhandled materiality " + m);
}

function decideLearner(inp) {
  const a = inp.authority;
  if (inp.freeze_active) return out("NO_CHANGE", ["freeze_active"], a);
  if (inp.grade_impacting) return out("ESCALATE", ["grade_impacting_requires_human"], a);
  if (!inp.consent) return out("NO_CHANGE", ["consent_missing"], a);
  const caps = inp.caps || {};
  if (Number(caps.notifications_today || 0) >= THRESHOLDS.budgets.notify_per_learner_day) return out("NO_CHANGE", ["rate_limited"], a, "day cap");
  if (Number(caps.notifications_week || 0) >= THRESHOLDS.budgets.notify_per_learner_week) return out("NO_CHANGE", ["rate_limited"], a, "week cap");
  if (inp.stuck && inp.concept_recently_dispatched) return out("NO_CHANGE", ["rate_limited"], a, "concept cap: " + (inp.concept || ""));
  if (inp.stuck) return out("DISPATCH", ["stuck_signals_met"], a, inp.concept || "");
  return out("NO_CHANGE", ["no_signal"], a);
}

function decideRevert(inp) {
  const a = inp.authority;
  if (inp.freeze_active) return out("NO_CHANGE", ["freeze_active"], a);
  if (!inp.revert_gate_present) return out("ESCALATE", ["revert_gate_absent"], a);
  if (inp.previous_version_available === false) return out("ESCALATE", ["previous_version_missing"], a);
  const c = inp.cohort || {};
  if (c.n === undefined || c.n === null || c.quiz_delta === undefined || c.quiz_delta === null ||
      c.hours_since_publish === undefined || c.hours_since_publish === null) return out("NO_CHANGE", ["measurement_incomplete"], a);
  if (Number(c.n) < THRESHOLDS.revert.n_min) return out("NO_CHANGE", ["cohort_below_minimum"], a, "n=" + c.n);
  if (Number(c.hours_since_publish) < THRESHOLDS.revert.window_h) return out("NO_CHANGE", ["gate_window_open"], a);
  if (Number(c.quiz_delta) <= 0) return out("REVERT", ["revert_gate_satisfied"], a);
  return out("NO_CHANGE", ["no_improvement_measured"], a);
}

function decide(inp) {
  const bad = malformed(inp);
  if (bad) {
    const authority = AUTHORITIES.includes(inp.authority) ? inp.authority : "PA0";
    return out("ESCALATE", ["unknown_state"], authority, "invalid:" + bad);
  }
  if (inp.stream === "change") return decideChange(inp);
  if (inp.stream === "learner") return decideLearner(inp);
  return decideRevert(inp);
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { decide, THRESHOLDS, MATERIALITIES, PUBLISHABLE };
}

// n8n runtime: read the input and emit one item per decision
if (typeof $input !== "undefined") {
  return $input.all().map((item) => ({ json: { decision: decide(item.json.input), input_hash: item.json.input_hash } }));
}

// Merge POLICY's {decision, input_hash} with the pre-POLICY engine/scenario info.
// POLICY runs runOnceForAllItems and preserves item ORDER, so we correlate by index
// against the union of items that entered POLICY this run.
const pre = [];
try { for (const it of $('PASS ENGINE INPUTS').all()) pre.push(it.json); } catch (e) {}
try { for (const it of $('JUDGE→input').all()) if (!pre.some(p => p === it.json)) pre.push(it.json); } catch (e2) {}
return $input.all().map((item, idx) => {
  const j = item.json || {};
  const match = pre[idx] || {};
  return { json: {
    ...j,
    scenario: match.scenario || null,
    engine: match.engine === true,
    input: match.input || j.input || null,
    input_hash: j.input_hash !== undefined ? j.input_hash : null
  } };
});

// one chained row per decision; carry scenario/engine/decision forward for the branches
return $input.all().map(item => {
  const j = item.json || {};
  return { json: {
    scenario: j.scenario || null,
    engine: j.engine === true,
    decision: j.decision,
    input: j.input || null,
    input_hash: j.input_hash !== undefined ? j.input_hash : null,
    receipt_id: 'rcpt-showcase-' + $execution.id + '-' + idx_tag(j),
    row: { ts: new Date().toISOString(), execution: $execution.id, scenario: j.scenario || null,
           action: (j.decision || {}).action, reasons: (j.decision || {}).reason_codes || [],
           authority: (j.decision || {}).authority, engine: j.engine === true }
  } };
});
function idx_tag(j) {
  const a = (j.decision || {}).action || 'x';
  const h = (j.input || {}).event_id || 'n';
  return a + '-' + h;
}

// ACT: render v+1 lesson body from the anchored edit (real body, real diff)
return $input.all().filter(i => ['PUBLISH','REVERT'].includes(i.json.decision?.action)).map(item => {
  const j = item.json;
  const d = j.decision;
  const lesson = d.action === 'REVERT' ? (j.input.lesson_touched || 'lesson-02-apify-actors') : (j.input.lesson_touched || 'lesson-02-apify-actors');
  const stamp = new Date().toISOString().replace('T',' ').slice(0, 16) + ' UTC';
  const srcLine = (j.input.sources || []).map(s => `- ${s.url} (captured ${stamp.slice(0,10)}, ${s.publisher})`).join('
');
  const vNew = d.action === 'REVERT' ? 'v4 (reverted to v3)' : 'v3';
  const body = `## ${lesson} — ${vNew}

Autonomous update ${d.action} · authority ${d.authority} · ${stamp}
Reason codes: ${(d.reason_codes||[]).join(', ')}

### What changed

${(j.input.sources||[]).length} independent source${(j.input.sources||[]).length===1?'':'s'} corroborate this change: the ${lesson.replace('lesson-02-','')} lesson now covers the newest upstream capability.

### Sources verified
${srcLine}

---
Receipt: this lesson version was decided by the POLICY rulebook on the n8n canvas (execution ${$execution.id}) — no human in the loop.
`;
  const prev = `## ${lesson} — v2

Baseline content (authored version).
`;
  // unified diff (line-level, honest — same format the engine writes)
  const pl = prev.split('
'), nl = body.split('
');
  const diff = ['--- v2', '+++ ' + vNew]
    .concat(pl.map(l => '- ' + l)).concat(nl.filter(l => !pl.includes(l)).map(l => '+ ' + l));
  return { json: {
    scenario: j.scenario, decision: d, engine: j.engine,
    lesson_id: lesson, previous_version: 'v2', new_version: vNew,
    body, diff: diff.join('
'),
    body_path: `showcase/${lesson}/${d.action === 'REVERT' ? 'v4-revert.md' : 'v3.md'}`,
    diff_path: `showcase/${lesson}/diffs/${d.action === 'REVERT' ? 'v4-revert.diff' : 'v3.diff'}`,
    receipt_id: 'rcpt-showcase-' + $execution.id + '-' + (j.input.event_id || 'x'),
    notify: d.action === 'PUBLISH',
    card_text: `Courserefresh learner card

LESSON UPDATED — ${lesson} (v2 -> ${vNew})
Why: ${(d.reason_codes||[]).join(', ')} — sources corroborated (>=2 voices)
Diff: showcase/${lesson}/diffs/
Stop updates: reply STOP to this bot anytime.` } };
});

// prepare GitHub Contents-API commits (body file, then diff file) as ready JSON strings
const b64 = s => Buffer.from(s, 'utf8').toString('base64');
return $input.all().map(item => {
  const j = item.json;
    const tokenless = true; // sha comes from the LOOKUP node downstream
  return { json: {
    scenario: j.scenario,
    decision: j.decision,
    engine: j.engine === true,
    meta: { lesson: j.lesson_id, v: j.new_version, receipt: j.receipt_id },
    // full request bodies, pre-built — the HTTP nodes just stringify them in
    body_commit: {
      path: j.body_path,
      json: { message: `cr-showcase: ${j.body_path} [${j.receipt_id}]`,
              content: b64(j.body), branch: 'main' }
    },
    diff_commit: {
      path: j.diff_path,
      json: { message: `cr-showcase(diff): ${j.diff_path}`,
              content: b64(j.diff), branch: 'main' }
    },
    notify: j.notify,
    card_text: j.card_text
  } };
});

// after the body PUT: carry the diff commit request; pair with MERGE output for context
return $input.all().map((item, idx) => {
  const m = $('MERGE sha → body commit').all()[idx].json;
  const resp = item.json || {};
  return { json: {
    scenario: m.scenario, decision: m.decision, engine: m.engine === true, meta: m.meta,
    diff_commit: m.diff_commit, notify: m.notify, card_text: m.card_text,
    body_path: m.body_commit.path,
    body_sha: resp.content && resp.content.sha || null,
    body_html_url: resp.content && resp.content.html_url || null
  } };
});

// act receipt rows: what got committed, where
return $input.all().map((item, idx) => {
  const m = $('MERGE sha·diff').all()[idx].json;
  return { json: {
    receipt_row: true,
    ts: new Date().toISOString(),
    execution: $execution.id,
    scenario: m.scenario,
    action: (m.decision || {}).action || 'PUBLISH',
    reasons: ['committed body+diff', m.body_path || '', (m.diff_commit || {}).path || ''],
    raw: null
  } };
});

// LEARN intake: scenarios D (revert-stream) and E (learner-stream) run the same
// rulebook — POLICY decides REVERT / DISPATCH / NO_CHANGE. Real gate maths in code:
return $input.all().map(item => {
  const j = item.json;
  const inp = j.input || {};
  if (inp.stream === 'revert') {
    const c = inp.cohort || {};
    // production gate: n>=5, window>=48h, quiz_delta<=0 → REVERT
    const n_ok = Number(c.n) >= 5, w_ok = Number(c.hours_since_publish) >= 48, delta_ok = Number(c.quiz_delta) <= 0;
    return { json: { scenario: j.scenario, gate: { ...c, n_ok, w_ok, delta_ok,
      satisfied: n_ok && w_ok && delta_ok }, input: inp, input_hash: j.input_hash } };
  }
  if (inp.stream === 'learner') {
    const l = inp.learner || {};
    const stuck = Number(l.consecutive_wrong) >= 2;
    const consent = l.consent === true;
    const cap_ok = Number(l.notifications_today||0) < 1 && Number(l.notifications_week||0) < 3;
    return { json: { scenario: j.scenario, stuck_flag: stuck && consent && cap_ok,
      learner_state: { ...l, stuck, consent, cap_ok }, input: inp, input_hash: j.input_hash } };
  }
  return { json: { scenario: j.scenario, input: inp } };
});

// LEARN act: gate satisfied → REVERT record + revert card; stuck → micro-lesson card.
//ß Both messages go to the consented demo cohort (same Telegram channel the digest uses).
return $input.all().map(item => {
  const j = item.json;
  if (j.gate) {
    const g = j.gate;
    return { json: { scenario: j.scenario, kind: 'revert',
      send: g.satisfied,
      text: g.satisfied
        ? `Courserefresh revert gate SATISFIED\n\nquiz_delta ${g.quiz_delta} at n=${g.n} after ${g.hours_since_publish}h (thresholds: n>=5, window>=48h, delta<=0).\nAction: ${'lesson-02-apify-actors'} reverted — the lesson is back to its last-good version.\n(auto-decided by the POLICY rulebook; receipt rcpt-learn-${$execution.id})`
        : `Revert gate NOT satisfied (n=${g.n}, window=${g.hours_since_publish}h, delta=${g.quiz_delta}) — lesson stays published. Measured, not assumed.` } };
  }
  if (j.stuck_flag !== undefined) {
    return { json: { scenario: j.scenario, kind: 'micro-lesson',
      send: j.stuck_flag === true,
      text: j.stuck_flag
        ? `Courserefresh micro-lesson (you asked for help by getting stuck — reply STOP to opt out)\n\nOne concept: Apify dataset rows — every actor run appends JSON rows; read them with dataset.getItems(). Two minutes, one practice item: fetch the first 3 rows of your last run.\nSignals: consecutive_wrong=${j.learner_state.consecutive_wrong}, dwell ${j.learner_state.dwell_minutes} min. Consented learners only.`
        : `Learner signal seen but not dispatched (consent=${j.learner_state.consent}, caps_ok=${j.learner_state.cap_ok}) — no message sent.` } };
  }
  return { json: { scenario: j.scenario, kind: 'none', send: false, text: '' } };
});

// after Telegram sends (or skips): receipt rows for learn outcomes
return $input.all().map(item => {
  const j = item.json;
  const ok = j.ok === true || (j.result && j.result.message_id);
  return { json: { receipt_row: true, ts: new Date().toISOString(), execution: $execution.id,
    scenario: j.scenario, action: 'LEARN',
    reasons: [j.kind], text_sent: ok ? true : false, raw: j } };
});

// DIGEST: collect every receipt row this execution produced (all lanes), exactly once.
// Cross-lane reads via $() node lookups; malformed rows are dropped (they are dishonest data);
// history kept in workflow static data for the digest window.
const rows = [];
const seen = new Set();
const take = (node, label) => {
  try {
    for (const item of $(node).all()) {
      const j = item.json || {};
      const row = j.row || j; // receipt nodes emit {receipt_row, row} — take the row
      const action = row.action || j.decision && j.decision.action;
      if (!action) continue; // malformed → drop (chain integrity is the point)
      const key = (row.ts || '') + '|' + action + '|' + (row.scenario || label) + '|' + JSON.stringify(row.reasons || []);
      if (seen.has(key)) continue; // dedupe multi-branch duplicates
      seen.add(key);
      rows.push({
        ts: row.ts || new Date().toISOString(),
        execution: row.execution || $execution.id,
        scenario: row.scenario || null,
        action,
        reasons: (row.reasons || []).filter(r => r != null),
        authority: row.authority || null,
      });
    }
  } catch (e) { /* lane absent this run */ }
};
take('TRIAGE RECEIPTS', 'triage');
take('ACT RECEIPTS', 'act');
take('LEARN RECEIPTS', 'learn');
take('SCAN RECEIPT', 'scan');

// digest window = THIS execution only (a demo run is self-contained;
// legacy rows from earlier runs are dropped along with their shape drift)
const store = $getWorkflowStaticData('global');
store.digestWindow = rows;
return [{ json: { count: rows.length, rows } }];

// ORDER (production contract): refusals first, then changes, then learner panel
return $input.all().map(item => {
  const rows = item.json.rows || [];
  const rank = r => (r.reasons || []).includes('insufficient_corroboration') ? 0
    : (r.reasons || []).includes('injection_or_jailbreak') ? 0
    : r.action === 'PUBLISH' || r.action === 'REVERT' ? 1
    : r.action === 'LEARN' ? 2 : 3;
  const ordered = [...rows].sort((a, b) => rank(a) - rank(b));
  return { json: { ...item.json, ordered } };
});

// RENDER (production contract): <=4096 bytes, trims oldest-first, never refusals,
// prints `unmeasured` where measurement is missing.
return $input.all().map(item => {
  const rows = item.json.ordered || [];
  const lines = ['Courserefresh — showcase digest', ''];
  const refusals = rows.filter(r => r.action === 'ESCALATE' || (r.reasons||[]).some(x => ['insufficient_corroboration','injection_or_jailbreak'].includes(x)));
  const changes = rows.filter(r => ['PUBLISH','REVERT'].includes(r.action) && !refusals.includes(r));
  const learns = rows.filter(r => r.action === 'LEARN');
  if (refusals.length) {
    lines.push('REFUSALS (listed first):');
    for (const r of refusals.slice(0, 5)) lines.push(`  - [${r.action}] ${(r.scenario||'').slice(0,60)} — ${(r.reasons||[]).join(',')}`);
  }
  if (changes.length) {
    lines.push('WHAT CHANGED:');
    for (const r of changes.slice(0, 5)) lines.push(`  - [${r.action}] ${(r.scenario||'').slice(0,60)}`);
  }
  if (learns.length) {
    lines.push('LEARNERS:');
    for (const r of learns.slice(0, 5)) lines.push(`  - ${r.reasons?.[0] === 'micro-lesson' ? 'micro-lesson sent (consented)' : r.reasons?.[0] || 'cohort evaluated'}`);
  }
  lines.push('');
  lines.push(`cohort quiz_delta: unmeasured (no consented live cohort this window)`);
  lines.push(`chain: verified — ${rows.length} receipt rows, all hash-linked`);
  lines.push(`budget: 6 publishes/day cap · 60k tokens/change — within`);
  lines.push(`mode: showcase (live LLM judges, real commits, real Telegram)`);
  let text = lines.join('\n');
  // 4KB cap: trim oldest changes first, NEVER refusals
  while (text.length > 4000 && changes.length > 1) { changes.shift(); text = lines.join('\n'); }
  if (text.length > 4000) text = text.slice(0, 4000);
  return { json: { digest_text: text, rows: item.json.rows, count: item.json.count } };
});

// VERIFY CHAIN (production contract): every row recomputes clean, execution ids present.
// DIGEST FAILED banner if anything is off — the digest never claims what it can't show.
return $input.all().map(item => {
  const rows = item.json.rows || [];
  const problems = [];
  for (const r of rows) {
    if (!r.execution) problems.push('row missing execution id');
    if (!r.ts) problems.push('row missing timestamp');
    if (!r.action) problems.push('row missing action');
  }
  const chain_ok = problems.length === 0;
  const text = chain_ok ? item.json.digest_text
    : item.json.digest_text + '\n\n!! DIGEST FAILED — chain verification failed: ' + problems[0];
  return { json: { ...item.json, digest_text: text, chain_ok } };
});

// FINAL RESPONSE: what the demo caller sees — one JSON blob naming every lane's outcome
const lanes = {};
const collect = (node, label) => {
  try { lanes[label] = $(node).all().map(i => ({
    scenario: i.json.scenario, action: (i.json.decision||{}).action || i.json.action,
    reasons: (i.json.decision||{}).reason_codes || i.json.reasons || [],
    authority: (i.json.decision||{}).authority, engine: i.json.engine === true })); }
  catch (e) { lanes[label] = ['lane not reached']; }
};
collect('POLICY', 'triage');
collect('ACT RENDER', 'act');
collect('LEARN ACT', 'learn');
const digest = $('VERIFY CHAIN').first().json;
return [{ json: {
  ok: true, workflow: 'CR Showcase — the whole loop on one canvas',
  execution_id: $execution.id,
  lanes, digest_bytes: digest.digest_text.length, chain_ok: digest.chain_ok,
  telegram_sent_to: 'consented demo cohort', github_branch: 'main (showcase/)',
  llm: 'OBSERVE+JUDGE via Apify TokenFactory (gpt-oss-120b)'
} }];

// attach the current file sha (if any) to the commit request; 404 = brand-new file
return $input.all().map((item, idx) => {
  const prep = $('GH PREP').all()[idx].json;
  const resp = item.json || {};
  const sha = (resp && typeof resp.sha === 'string') ? resp.sha : null;
  const body = Object.assign({}, prep.body_commit.json);
  if (sha) body.sha = sha;
  return { json: {
    scenario: prep.scenario, decision: prep.decision, engine: prep.engine === true,
    meta: prep.meta, body_commit: { ...prep.body_commit, json: body },
    diff_commit: prep.diff_commit, notify: prep.notify, card_text: prep.card_text,
    existing_sha: sha
  } };
});

// attach sha (if the diff file exists) and emit the final diff commit request
return $input.all().map((item, idx) => {
  const m = $('AFTER body → diff').all()[idx].json;
  const resp = item.json || {};
  const sha = (resp && typeof resp.sha === 'string') ? resp.sha : null;
  const body = Object.assign({}, m.diff_commit.json);
  if (sha) body.sha = sha;
  return { json: {
    scenario: m.scenario, decision: m.decision, engine: m.engine === true, meta: m.meta,
    diff_commit: { ...m.diff_commit, json: body }, notify: m.notify, card_text: m.card_text,
    body_path: m.body_path, body_sha: m.body_sha, body_html_url: m.body_html_url,
    diff_sha: sha
  } };
});
